  "قد تشمل الحصة خطط التغيير، البوتات، القوالب، الرسائل المجدولة، والتحليلات بحسب الكتالوج الحالي.": "The quota may include change plans, bots, templates, scheduled messages, and analytics based on the current catalog.",
  "قبل بلوغ الحد": "Before reaching the limit",
  "تظهر تنبيهات الاستخدام في لوحة الحساب. خفف العمليات الكبيرة أو انتقل إلى خطة أعلى إذا احتجت سعة أكبر.": "Usage alerts appear on the account dashboard. Reduce large operations or upgrade to a higher plan if you need more capacity.",
  "الاستخدام الممنوع": "Prohibited Use",
  "لا تستخدم الأتمتة للإزعاج، أو الدعوات الجماعية غير المرغوبة، أو تجاوز Discord، أو إنشاء نشاط ضار متكرر.": "Do not use automation for annoyance, unwanted mass invites, exceed Discord, or create frequent harmful activities.",
  "الأسئلة المتكررة": "Frequently Asked Questions",
  "إجابات مباشرة عن الحساب، الصلاحيات، الخطط، المعاينة، والدعم.": "Direct answers about the account, permissions, plans, preview, and support.",
  "هل أستطيع تجربة Diskoko دون اشتراك مدفوع؟": "Can I try Diskoko without a paid subscription?",
  "نعم. خطة Free مجانية وتمنحك تجربة إدارة فعلية ضمن حدودها. إذا لم تكن مسجلًا، ينقلك زر البدء إلى تسجيل الدخول، وبعده تفتح لوحة الحساب.": "Yes. The Free plan is free and gives you a real server management experience within its limits. If you are not registered, the Start button will take you to sign in, and then you will open your account dashboard.",
  "هل يطبّق Diskoko التغييرات تلقائيًا؟": "Does Diskoko apply changes automatically?",
  "لا. المسار الصحيح هو إنشاء مسودة، مراجعة العمليات والصلاحيات، ثم اعتماد التنفيذ. راجع دائمًا التغييرات الحساسة قبل تطبيقها.": "No. The correct path is to create a draft, review the processes and permissions, then approve the execution. Always review sensitive changes before applying them.",
  "ما الصلاحيات المطلوبة؟": "What permissions are required?",
  "تختلف حسب الوظيفة. نعرض الصلاحيات المطلوبة في مسار الربط، ونوصي بمنح أقل صلاحيات تكفي للوظيفة التي تريدها.": "It varies depending on the role. We show the required permissions in the connection path, and we recommend giving the least permissions needed for the role you want.",
  "هل أحتاج إلى خبرة في Discord؟": "Do I need experience with Discord?",
  "لا تحتاج إلى خبرة تقنية. تبدأ من قالب أو طلب واضح، ثم تعدّل المعاينة قبل النشر. تبقى معرفة صلاحيات سيرفرك ومسؤوليتك عن المحتوى مهمة.": "No technical experience is needed. Start from a template or clear request, then review the preview before publishing. Knowledge of your server's permissions and your responsibility for the content is still important.",
  "كيف أطلب الدعم؟": "How do I request support?",
  "استخدم صفحة البلاغات أو ادخل سيرفر Discord الخاص بالدعم. أرسل وصفًا مختصرًا ووقت المشكلة ورابط الرسالة أو المعرّف إن أمكن.": "Use the complaint page or enter the Discord support server. Send a brief description, the time of the problem, and the message or identifier if possible.",
  "تخطي إلى مساحة العمل": "Skip to workspace",
