  "ابدأ بقالب جاهز، خصّص الترحيب والدعم والفعاليات، وراجع شكل كل تغيير قبل نشره. نفّذ عبر بوت ديسكوكو أو بوتك الخاص حسب إعداد سيرفرك.": "Start with a ready template, specialize the welcome, support, and events, and review the appearance of each change before publishing. Execute via the Diskoko bot or your own bot according to your server settings.",
