  "قوالب سيرفرات جاهزة": "Ready server templates",
  "تصنيفات وقنوات ورتب وترحيب ودعم في مسودة قابلة للتعديل، مع خيار الإضافة أو الاستبدال بعد مراجعة واضحة.": "Categories, channels, roles, welcome, and support in an editable draft, with the option to add or replace after clear review.",
  "مساعد ديسكوكو AI": "Diskoko AI Assistant",
  "اكتب ما تريده، واختر من مكتبة القوالب لإنشاء بطاقات وقواعد وفعاليات. تظهر المعاينة والتفاصيل قبل الموافقة.": "Write what you need, choose from the template library to create cards, rules, and events. Preview and details appear before approval.",
