  "ابدأ مجانًا، وارفع السعة عندما يحتاج مجتمعك. الاشتراك السنوي يعادل عشرة أشهر ويحصل على شهرين مجانًا.": "Start free, and increase the capacity when your community needs it. Annual subscription equals ten months and gets two months free.",
