  "كيف تعمل الميزات؟": "How do the Features Work?",
  "القوالب الجاهزة قابلة للتعديل قبل التطبيق. ويمكنك اختيار بوت ديسكوكو أو ربط بوتك الخاص لكل سيرفر. حد «تصاميم البوتات» يعني المسودات المحفوظة؛ حفظ التصميم وحده لا يشغّل بوتًا جديدًا.": "Ready Templates Can Be Edited Before Use. You Can Choose the Diskoko Bot or Connect Your Own Bot for Each Server. The 'Bot Templates' Limit Means Saved Drafts; Saving the Design Alone Does Not Activate a New Bot.",
  "الخطوة التالية": "Next Step",
  "اختر باقتك، وراجع التفاصيل قبل تسجيل الطلب.": "Choose Your Plan, and Review the Details Before Submitting the Request.",
  "وسائل الدفع قيد الربط حاليًا؛ لن يُخصم منك شيء عند تسجيل الطلب.": "Payment Methods Are Currently Linked; No Charges Will Be Applied When Submitting the Request.",
  "تنبيه قبل الحد": "Notification Before the Limit",
  "يظهر تنبيه عند 80٪، وتتوقف العملية الجديدة فقط عند بلوغ 100٪.": "Notification shows at 80%, and the new process stops only when it reaches 100%.",
  "تغيير الخطة": "Change Plan",
  "عند تفعيل بوابة الدفع، تُفعّل الترقية بعد تأكيد العملية. طلب الترقية الحالي لا يغيّر باقتك.": "When the payment gateway is enabled, the upgrade is activated after confirming the process. The current upgrade request does not change your plan.",
  "لا رسوم مخفية": "No hidden fees",
  "نعرض مبلغ طلب الترقية التقديري الآن. ستظهر الضريبة ووسيلة الدفع النهائية عند ربط البوابة.": "We now show the estimated upgrade amount. Tax and final payment method will be displayed when the gateway is connected.",
