  "شكل تقريبي داخل Discord؛ سيستخدم السيرفر اسمه وصورته الحقيقيين.": "Approximate Appearance in Discord; the Server will use its real name and avatar.",
  "الرتب وصلاحياتها": "Roles and Permissions",
  "افتح Discord ← إعدادات السيرفر ← الرتب، وارفع رتبة": "Open Discord ← Server Settings ← Roles, and raise the role",
  "البوت الذي اخترته للتنفيذ": "The bot you selected for execution",
  "فوق الرتب التي سيُنشئها أو يعدّلها أو يحذفها. للتنصيب أو الاستبدال يحتاج إدارة القنوات وإدارة الرتب؛ ولنشر بطاقات الترحيب والدعم يحتاج أيضًا عرض القنوات وإرسال الرسائل والروابط المضمنة.": "Above the roles that will be created, edited, or deleted. To assign or replace roles, you need Channel Management and Role Management; to publish welcome and support cards, you also need Channel View and Message Sending with Embedded Links.",
  "يمكن منح بوت موثوق صلاحية": "A trusted bot can be granted permissions",
  "إذا أردت إعدادًا شاملًا، لكنها صلاحية واسعة واختيارية، ولا تُغني عن رفع رتبته فوق الرتب المستهدفة.": "If you want a comprehensive setup, but it's a broad and optional permission, and it doesn't replace raising the role above the target roles.",
  "ابنِ مجتمعك كما تتخيله": "Build your community as you imagine it",
  "ابدأ بهيكل جاهز، ثم اضبط كل قناة ورتبة وميزة قبل التنصيب. ستشاهد القالب داخل معاينة Discord وتراجع الفروق قبل أي تغيير.": "Start with a ready framework, then adjust each channel, role, and feature before deployment. You will see the template inside Discord Preview and see the differences before any changes.",
