  "تصميم صورة مركبة — خيارات متقدمة": "Composite Image Design — Advanced Options",
  "اختر قناة النشر من قسم الوظيفة والقناة": "Select Publication Channel from the Function and Channel Section",
  "زر رابط": "Link Button",
  "يختار العضو رتبة اهتمام عادية بنفسه، ويمكنه إزالتها بالضغط مرة أخرى.": "The member selects a regular interest role for themselves, and can remove it by pressing again.",
  "يقدّم العضو اقتراحًا خاصًا؛ ينشره الفريق بعد المراجعة ثم يصوّت عليه المجتمع.": "The member submits a special proposal; the team publishes it after review and then the community votes on it.",
  "يرسل العضو بلاغًا خاصًا إلى قناة الإدارة، دون نشره للعامة.": "The member sends a special report to the Administration Channel, without publishing it publicly.",
  "يسجّل العضو مشاركته أو يلغيها، مع موعد وعدد أماكن اختياريين.": "The member records their participation or cancels it, with a scheduled time and optional number of places.",
  "يتقدم العضو لرتبة أو فريق، ويراجع طلبه المشرفون في قناة خاصة.": "The member applies for a role or team, and the supervisor reviews the request in a private channel.",
  "يعرض البوت إجابة محددة للعضو عند الضغط على زر اللوحة.": "The bot provides a specific response to the member when the member presses the board button.",
  "يراجع الفريق أعمال الأعضاء وروابطها، وينشر المقبول منها.": "The team reviews members' works and their links, and publishes the accepted ones.",
  "يستقبل الفريق طلب منتج أو خدمة في قناة خاصة ويتابع إنجازه. لا يتضمن دفعًا تلقائيًا.": "The team receives a product or service request in a private channel and follows up on its progress. It does not include automatic payment.",
  "يسجل المتعلم إنجازه واحتياجه للمساعدة؛ يراجع المرشد تقدمه حتى الاكتمال.": "The learner records their progress and need for assistance; the mentor reviews their progress until completion.",
  "ينشئ الفريق مهمة داخل قناة خاصة، ثم يحدد قبولها وإنجازها.": "The team creates a task within a private channel, then determines its acceptance and completion.",
  "جهز جيف آواي في #[القناة] لجائزة [الجائزة] لمدة [المدة بالدقائق] دقيقة، مع [عدد الفائزين] فائز. اعرض التفاصيل في بطاقة المراجعة قبل النشر.": "Jeff Ayers prepared a [Award] for [Channel] for [Duration in minutes] minutes, with [Number of Winners] winners. Display the details in the review card before publishing.",
  "جهز جيف آواي لجائزة اشتراك [المدة] في #[القناة]، ينتهي بعد [عدد الساعات] ساعة، وفائز واحد.": "Jeff Ayers prepared an [Award] for [Duration] in [Channel], ending after [Number of Hours] hours, with one winner.",
  "نظم جيف آواي في #[القناة] لجائزة [الجائزة]، لمدة [المدة] دقيقة، واختر [عدد الفائزين] فائزين.": "Jeff Ayers organized a [Award] in [Channel] for [Duration] minutes, selecting [Number of Winners] winners.",
  "جهز لوحة تذاكر دعم في #[القناة] بعنوان [العنوان]، ووصفها [الوصف]. اعرض الخطة قبل النشر.": "Jeff Ayers prepared a support ticket board in [Channel] with the title [Title], and described it as [Description]. Display the plan before publishing.",
  "جهز لوحة تذاكر دعم للعملاء في #[القناة]، بعنوان [اسم الخدمة]، مع زر يفتح محادثة خاصة لصاحب الطلب وفريق الدعم. اجعل استلام التذكرة لفريق الدعم فقط.": "Jeff Ayers prepared a support ticket board for customers in [Channel], with the title [Service Name], including a button that opens a private conversation with the requester and the support team. Make ticket submission only available to the support team.",
  "جهز لوحة تذاكر لطلبات المساعدة في #[القناة]. اجعل العنوان واضحًا والوصف ودودًا ومختصرًا.": "Jeff Ayers prepared a ticket board for help requests in [Channel]. Make the title clear, the description friendly and concise.",
  "اكتب رسالة أنيقة عن [الموضوع] للنشر في #[القناة]. سأرفق صورة مع الرسالة؛ اعرض النص للمراجعة قبل النشر.": "Write a polished message about [Topic] for publication in [Channel]. I will attach an image with the message; review the text for editing before publishing.",
  "جهز بطاقة ترحيب تلقائية للأعضاء الجدد في #[القناة] بعنوان [العنوان] ونص [الوصف] وصورة العضو.": "Jeff Ayers prepared an automatic welcome card for new members in [Channel] with the title [Title], text [Description], and member image.",
  "جهز إعلان فعالية [الاسم] بتاريخ [الوقت] في #[القناة] مع زر تسجيل اختياري وعدّاد للمشاركين.": "Jeff Ayers prepared an event announcement for [Name] on [Time] in [Channel] with an optional registration button and a participant counter.",
  "جهز بطاقة قوانين لسيرفري في #[القناة]. أريد اختيار طريقة العرض وتعديل القوانين واللون والصورة قبل النشر.": "Jeff Ayers prepared a rule card for the server in [Channel]. I want to choose the display method, edit the rules, color, and image before publishing.",
  "أريد التحكم في #[القناة]: من يستطيع الكتابة، اسم القناة ووصفها، بطء المحادثة والمحتوى الحساس. اعرض التغييرات للمراجعة قبل التنفيذ.": "I want to manage #[Channel]: Who can write, the channel name and description, slow down the conversation and sensitive content. Show the changes for review before implementation.",
  "أنشئ حدث Discord أصليًا لسيرفري بعنوان [اسم الحدث]، مع الموعد والمكان والوصف وصورة الغلاف. اعرض نموذج الحدث للمراجعة قبل إنشائه في Events.": "Create a Discord event originally for your server with the title [Event Name], including the date, location, description, and cover image. Show the event template for review before creating it in Events.",
  "جهز استطلاعًا تفاعليًا في #[القناة] عن [السؤال] بخيارات [الخيار الأول] و[الخيار الثاني]. اعرض التفاصيل قبل النشر.": "Prepare an interactive poll in #[Channel] about [Question] with options [Option One] and [Option Two]. Show the details before publishing.",
