  "تعذر التحقق من السيرفر": "Server verification failed",
  "العودة إلى الحساب": "Return to Account",
  "استخدم diskoko لإدارة مجتمعات قانونية ومحترمة. يمنع استخدام الأتمتة للتحايل على Discord أو إزعاج المستخدمين أو جمع بياناتهم دون إذن. يمكن إيقاف الحسابات التي تخالف هذه القواعد بعد مراجعة مناسبة.": "Use diskoko to manage legal and respectful communities. Automating to bypass Discord, annoy users, or collect data without permission is prohibited. Accounts that violate these rules may be suspended after appropriate review.",
  "نظام البلاغات": "Reporting System",
  "يمكن لمالك المجتمع إرسال بلاغ عن إساءة أو حساب مشبوه من لوحة التحكم. نسجل البلاغ، نصنفه، ونوفر حالة واضحة: مستلم، قيد المراجعة، أو مغلق. لا ينفذ النظام عقوبة حساسة بلا سياسة ومراجعة بشرية.": "Community owners can report abuse or suspicious accounts from the dashboard. We log, classify, and provide clear status: received, under review, or closed. The system does not enforce sensitive penalties without a policy and human review.",
  "حدود الاستخدام": "Usage Limits",
  "تتغير الحدود حسب الخطة ونوع العملية. نطبق حصصًا على تصميمات AI والرسائل والتحليلات والعمليات المكلفة، مع تنبيه قبل الوصول إلى الحد ومنع الاستهلاك المفاجئ بدل رسوم غير متوقعة.": "Limits vary based on plan and operation type. We apply quotas on AI designs, messages, analytics, and costly operations, with warnings before reaching limits and preventing sudden consumption instead of unexpected charges.",
  "نراقب مؤشرات مثل إنشاء سيرفرات متكرر، دعوات جماعية، رسائل متشابهة، تغييرات صلاحيات مفاجئة، ومحاولات تجاوز الحدود. المراقبة تعتمد على البيانات التشغيلية الضرورية فقط، ولا تعني قراءة خاصة غير لازمة.": "We monitor indicators such as repeated server creation, group invites, similar messages, sudden permission changes, and attempts to exceed limits. Monitoring relies only on necessary operational data and does not imply unauthorized access beyond what is necessary.",
  "ابدأ اللعب لتظهر نتيجتك": "Start playing to see your result",
  "اختيار الباقة": "Select a Plan",
  "مراجعة المبلغ": "Review the Amount",
  "طلب الترقية": "Request Upgrade",
  "باقة تناسب الخطوة الجاية لمجتمعك.": "A plan that fits the next step for your community.",
  "راجع الخطة والفترة والخصم قبل تسجيل الطلب. الدفع الإلكتروني لم يُفعّل بعد ولن يُخصم منك شيء الآن.": "Review the Plan, Duration, and Discount before submitting the request. Electronic payment is not yet activated and nothing will be deducted from you at this time.",
  "اختر الباقة": "Select a Plan",
  "مدة الاشتراك": "Subscription Duration",
  "سنوي · شهران مجانًا": "Yearly · two months free",
  "رمز الخصم": "Discount Code",
  "تطبيق": "App",
  "وسائل الدفع المخطط لها": "Planned Payment Methods",
  "مدى والبطاقات": "Credit and Debit Cards",
  "قيد الربط": "Linked",
  "تمارا": "Tamar",
  "هذه ليست شاشة تحصيل. اختيار الباقة يسجل طلب ترقية فقط، ولا تتغير خطتك حتى يُفعّل الدفع وتؤكد العملية عبر مزود معتمد.": "This is not a billing screen. Selecting a plan only registers an upgrade request and does not change your plan until the payment is processed and the process is confirmed through an authorized provider.",
  "ملخص الترقية": "Upgrade Summary",
  "سعر الباقة": "Plan Price",
  "مبلغ الطلب التقديري": "Estimated Request Amount",
  "ستظهر تفاصيل الضريبة ووسيلة الدفع النهائية عند تفعيل بوابة الدفع.": "Tax details and final payment method will appear when the payment gateway is activated.",
