  "فريق محدد": "Specified Team",
  "تم تحديث حالة السيرفر. راجع تعديلاتك؛ سيُفحص الرصيد والصلاحيات وترتيب الرتب مجددًا قبل التنفيذ.": "Server status has been updated. Review your changes; the balance and permissions and role order will be rechecked before execution.",
  "خفّض عدد التعديلات أو راجع رصيد باقتك، ثم أعد المراجعة.": "Reduce the number of changes or review your remaining balance, then re-review.",
  "أعد تسجيل الدخول، ثم راجع حالة التنفيذ قبل المحاولة.": "Log out and log back in, then review the execution status before attempting again.",
  "تحقق من صلاحيات حسابك والبوت، ومن وضع رتبة البوت فوق الرتبة المستهدفة.": "Check your account and bot permissions, and ensure the bot's role is above the target role.",
  "راجع حالة التنفيذ وما اكتمل في السجل قبل إنشاء تعديل جديد؛ لا تكرر الطلب إذا كان ما زال يعمل.": "Review the execution status and what has been completed in the log before creating a new change; do not repeat the request if it is still active.",
  "تعديلاتك محفوظة على هذا الجهاز. راجع الإعدادات والاتصال ثم أعد المراجعة.": "Your changes are saved on this device. Review the settings and connection then re-review.",
  "عرض حالة التنفيذ": "Execution Status",
  "تحقق بعد إصلاح المشكلة": "Check after fixing the issue",
  "توقف التنفيذ بعد خطأ سابق. أصلح السبب ثم اضغط «تحقق بعد إصلاح المشكلة» في التنبيه أعلى الصفحة، أو عدّل التغييرات.": "Stop execution after a previous error. Fix the cause and then click «Check after fixing the issue» in the notification at the top of the page, or modify the changes.",
  "السيرفر المستهدف:": "Target Server:",
  "الاستهلاك المتوقع:": "Expected Consumption:",
  "تغييرات في": "Changes in",
  "عناصر. لا يُستهلك رصيد عند المراجعة أو التأجيل؛ يُحسب فقط ما يُنفذ فعلًا، ولا تُحسب الإعدادات غير المتغيرة.": "Items. No credit is consumed during review or deferral; only what is actually executed is counted, and unchanged settings are not counted.",
  "مراجعة التغييرات وتطبيقها": "Review Changes and Apply Them",
  "لم يتغير أي إعداد. أزل العناصر غير المعدلة أو غيّر أحد خياراتها.": "No settings have changed. Remove the unmodified items or change one of their options.",
  "بالضغط على «نعم، أكد التنفيذ» توافق على تطبيق التغييرات المعروضة على هذا السيرفر.": "By clicking «Yes, Confirm Execution», you agree to apply the changes displayed on this server.",
  "إلغاء التغييرات": "Cancel Changes",
  ">نعم، أكد التنفيذ</button>": "<button>Yes, Confirm Execution</button>",
  "تغيّر السيرفر المختار. الخطة محفوظة في سجل السيرفر الأصلي ولم نطبقها.": "Change the selected server. The plan is saved in the original server's log and has not been applied.",
  "هناك تنفيذ من نافذة أخرى لهذا السيرفر. انتظر نتيجته وراجع السجل قبل المحاولة.": "There is an execution from another window for this server. Wait for the result and review the change log before attempting again.",
  "اكتملت التغييرات على سيرفرك. الاستهلاك الفعلي والتفاصيل في سجل التغييرات.": "The changes have been completed on your server. The actual consumption and details are in the change log.",
  "هذه الخطة تخص سيرفرًا آخر.": "This plan is for another server.",
  "أُوقف باقي التنفيذ وبقي السجل للمراجعة.": "The remaining execution has been stopped, and the log remains for review.",
  "اكتمل التطبيق.": "The application has been completed.",
  "توقفت الخطة: راجع السبب، أصلح الإعداد أو صلاحية البوت، ثم أنشئ مراجعة جديدة. لن نكرر الطلب نفسه.": "The plan has stopped: review the reason, fix the settings or the bot's validity, then create a new review. We will not repeat the same request.",
  "يمكن تنفيذ الباقي أو إيقافه.": "You can execute the remaining part or stop it.",
  "راجعت التغييرات وأوافق على تطبيقها على هذا السيرفر.": "The changes have been reviewed and I agree to apply them to this server.",
  "تم": "Done",
  "إيقاف بقية الخطة؟": "Stop the rest of the plan?",
  "سيبقى ما نُفذ فعليًا في Discord وفي سجل التغييرات. سيتوقف الباقي ولن يُحسب من رصيدك، ويمكنك بدء خطة جديدة.": "What has been executed actually will remain in Discord and the change log. The rest will stop and will not be counted from your balance. You can start a new plan.",
  "ستتوقف الخطة دون تنفيذ أو استهلاك رصيد، وسيبقى سجلها للمراجعة. يمكنك بدء خطة جديدة.": "The plan will stop without execution or balance consumption, and its log will remain for review. You can start a new plan.",
  "اكتملت التغييرات على سيرفرك وسُجلت في سجل التغييرات.": "Changes to your server have been completed and logged in the change log.",
  "اختيار الروم · تشغيل · إيقاف · التالي · مستوى الصوت": "Room · Play · Pause · Next · Volume Level",
  "كتالوج · معاينة · روابط مشاهدة · اقتراحات": "Catalog · Preview · Viewing Links · Suggestions",
  "تصميم اللوحة · إضافة فيديو · مشاهدة": "Dashboard Design · Add Video · Watch",
  "روابط · قنوات · ردود · إيموجيات · معاينة": "Links · Channels · Responses · Emojis · Preview",
  "أسئلة سريعة · حجر ورقة مقص · تخمين رقم · تحدي معلومات": "Quick Questions · Rock Paper Scissors · Number Guessing · Information Challenge",
  "اختر بوتًا متصلًا بهذا السيرفر.": "Select a bot connected to this server.",
  "الإعلانات": "Advertisements",
  "ترقبوا فعالياتنا القادمة!": "Wait for our upcoming events!",
  "تصميم واجهة المجتمع": "Community Interface Design",
  "لوحة لروابط مجتمعك وقنواته وردوده السريعة. يختار كل سيرفر وبوت تصميمه وأمره الخاص.": "A dashboard for your community's links, channels, and quick responses. Each server and bot chooses their own design and commands.",
  "＋ إضافة زر": "＋ Add Button",
  "لكل زر اسم وإيموجي ووظيفة. ألوان أزرار Discord هي الأزرق والرمادي والأخضر والأحمر؛ روابط القنوات والمواقع تظهر بلون الرابط الذي يحدده Discord.": "Each button has a name, emoji, and function. Discord button colors are blue, gray, green, and red; links and websites appear in the color specified by Discord.",
  "المعاينة قريبة من Discord. صورة البطاقة ستُرسل كملف، والأزرار الحقيقية تظهر تحتها. إذا لم تُفتح صورة Discord للعامة ستظهر البطاقة من دونها.": "Preview is close to Discord. The card image will be sent as a file, and the actual buttons will appear below it. If Discord's general image is not opened, the card will appear without it.",
  "اكتشف أقسام مجتمعنا من مكان واحد.": "Discover community sections from one place.",
  "حفظ التعديلات": "Save changes",
  "إنشاء اللوحة والأمر": "Create the board and the command",
