  "اختر من إيموجيات السيرفر": "Choose from server emojis",
  "📢 أو <:name:id>": "📢 or <:name:id>",
  "النص الذي يراه العضو": "The text that the member sees",
  "هذه اللوحة تعرض معلومات وروابط مشاهدة خارج Discord. كل عضو يشاهد بحسابه الخاص؛ البوت لا يبث Netflix أو أي فيلم داخل السيرفر.": "This panel displays information and links for watching outside Discord. Each member uses their own account; the bot does not stream Netflix or films inside the server.",
