  "رفض": "Reject",
  "حفظ المسودة": "Save the draft",
  "انشر اللوحة أولًا، ثم اختر القناة والموعد. الوقت الذي تدخله هنا حسب ساعة جهازك؛ تُحفظ المنطقة الزمنية مع المهمة. إذا حُذفت القناة أو نقصت صلاحيات البوت تتوقف المهمة وتظهر رسالة واضحة في سجل الرسائل المجدولة.": "Publish the board first, then select the channel and time. The time you enter here is based on your device's clock; the time zone is saved with the task. If the channel is deleted or the bot permissions are reduced, the task stops and a clear message appears in the scheduled message log.",
  "قناة اختيارات النادي": "Channel for selections",
