  "نُشرت لوحة النادي في Discord. جرّب الأمر والأزرار في القناة المختارة.": "The Club Board is published in Discord. Try it out and the buttons in the selected channel.",
  "أُزيلت لوحة النادي من القناة. الكتالوج محفوظ.": "The Club Board was removed from the channel. The catalog is saved.",
  "تعديل العمل": "Edit Work",
  "إضافة عمل للنادي": "Add Work to the Club",
  "العمل المنشور يحتاج رابط مشاهدة. الصورة اختيارية، لكن ستظهر علامة «بلا صورة» في الكتالوج حتى تضيفها. الروابط تفتح الخدمة خارج Discord.": "Published Work Needs a Viewing Link. The Image is optional, but it will show a 'No Image' mark in the catalog until you add it. Links open the service outside of Discord.",
