  "الخيارات المعروضة": "Available Options",
  "الوظائف المتاحة": "Available Functions",
  "تصميم لوحة الموسيقى": "Music Dashboard Design",
  "إنشاء لوحة يوتيوب": "Create YouTube board",
  "معاينة الألعاب المعلقة": "Preview paused games",
  "تصميم استديو الموسيقى": "Music studio design",
  "الأمر /موسيقى يضم خانتي «رابط» و«روم» معًا داخل Discord. بعد التنفيذ تظهر لوحة تشغيل بأزرار الإيقاف والتخطي ورفع الصوت وخفضه مباشرة؛ إدخال الرابط داخل بطاقة الرسالة نفسها غير مدعوم من Discord.": "The /music command includes both 'link' and 'room' together within Discord. After execution, a playback board with buttons for stop, skip, volume up and down appears directly; entering the link within the same message card is not supported by Discord.",
  "بنر عريض مع شعار": "Wide banner with logo",
  "بطاقة مركزة": "Focused card",
  "صورة الغلاف تظهر مكان صورة YouTube، والخلفية تظهر خلف البطاقة. ارفع الصور في Discord والصق روابط المرفقات. ألوان الأزرار محددة بما يتيحه Discord. ضع رابط فيديو YouTube عامًا أو رابط ملف صوتي. يظهر اسم المقطع تلقائيًا، وقد يتعذر تشغيل المقاطع المقيّدة أو غير المتاحة.": "Cover image appears in place of the YouTube image, and the background appears behind the card. Upload images in Discord and paste attachment links. Button colors are specific to what Discord provides. Enter a public YouTube video link or an audio file link. The video title appears automatically, and it may be difficult to play restricted or unavailable clips.",
  "معاينة لوحة الموسيقى": "Music board preview",
  "نيون مضيء": "Bright neon",
  "زجاجي": "Transparent",
  "هادئ": "Quiet",
  "الأغنية التي تعمل في الروم": "The song playing in the room",
  "جارٍ تحميل الصورة…": "Loading image...",
  "رابط صورة غير صالح": "Invalid image URL",
  "تعذر عرض البنر؛ استخدم رابط صورة متاحًا للعامة.": "Cannot display banner; use a publicly available image URL.",
  "افتح رابط الصورة وتأكد أنه متاح للعامة ولم تنتهِ صلاحيته.": "Open the image URL and ensure it is publicly available and not expired.",
  "حفظ تصميم اللوحة": "Save board design",
  "اسم الأمر مستخدم للوحة أخرى. اختر اسمًا مختلفًا.": "The command name is already used for another board. Choose a different name.",
  "لوحة موسيقى صوتية تفاعلية": "Interactive audio music board",
  "حُفظ تصميم لوحة الموسيقى.": "Saved music board design",
  "أنشئت لوحة الموسيقى. افتح الأمر في Discord وضع الرابط واختر الروم الصوتي.": "Board created. Open the command in Discord, paste the URL, and select the audio channel.",
  "تصميم لوحة يوتيوب": "YouTube board design",
  "صمّم اللوحة مرة واحدة. عند استخدام الأمر في Discord يظهر زر «إضافة فيديو»؛ يدخل العضو الرابط هناك ثم تظهر بطاقة الفيديو وزر المشاهدة.": "Design the board once. When using the command in Discord, a \"Add video\" button appears. The member enters the URL there, and then the video card and watch button appear.",
  "بنر عريض وشعار جانبي": "Wide banner and side logo",
  "صورة الفيديو بحجم بارز": "Video image at prominent size",
  "المشاهدة ثم إضافة فيديو": "Watch then add video",
  "إضافة فيديو ثم المشاهدة": "Add video then watch",
  "البنر والشعار يظهران ضمن حدود بطاقة Discord. المشاهدة تفتح مشغّل YouTube الرسمي؛ تشغيل الصوت داخل قناة Discord يحتاج مصدر صوت مصرحًا ببثّه.": "The banner and logo appear within the Discord card boundaries. Watching opens the official YouTube player; playing audio within a Discord channel requires a source with a broadcast permission.",
  "لوحة تفاعلية لإضافة ومشاهدة فيديو YouTube": "Interactive dashboard for adding and watching YouTube videos",
  "حُفظ تصميم لوحة يوتيوب.": "Save YouTube dashboard design",
  "أُنشئت اللوحة. افتح الأمر في Discord ثم أضف رابط الفيديو من زر اللوحة.": "The dashboard was created. Open the command in Discord then add the video link from the dashboard button.",
