  "أُضيف البوت؛ سيتصل بعد انتهاء مهلة Discord.": "The bot is added; it will connect after the Discord timeout.",
  "أُضيف بوتك الخاص. اختره للتنفيذ متى أردت.": "Add your bot. Choose it for execution when you want.",
  "هذا البوت أصبح منفذ المميزات الجديدة. اللوحات المنشورة بالبوتات الأخرى مستمرة.": "This bot has become the executor for new features. The published boards from other bots are continuing.",
  "تغيير اللقب في Discord": "Change the nickname in Discord",
  "جارٍ فحص صلاحيات البوت في السيرفر…": "Checking the bot's permissions in the server...",
  "شرح إعدادات Discord ↗": "Discord settings explanation ↗",
  "جارٍ قراءة اللقب من Discord…": "Reading the nickname from Discord...",
  "استقبال الأعضاء مفعّل": "Receiving members is enabled",
  "فعّل Server Members Intent ثم حدّث الربط": "Enable Server Members Intent and then update the connection",
  "فعّل Message Content Intent ثم حدّث الربط": "Enable Message Content Intent and then update the connection",
  "حفظ اسم اللوحة": "Save the board name",
  "هذا تغيير لهوية تطبيقك في Discord كله، وليس لهذا السيرفر فقط. يمكن لمالك الربط تغييره، وقد يطلب Discord الانتظار بين التغييرات.": "This is a change to your application's identity in Discord for all, not just this server. The owner can change it, and Discord may require waiting between changes.",
  "أفهم أن الاسم والصورة سيتغيران في جميع السيرفرات": "I understand that the name and image will change in all servers",
  "تحديث الهوية في Discord": "Update the identity in Discord",
  "أكّد أنك فهمت أن تغيير هوية البوت يشمل جميع السيرفرات.": "Confirm that you understand that changing the bot's identity includes all servers.",
  "اختر صورة PNG أو JPG أو WebP لا تتجاوز 250 كيلوبايت.": "Select a PNG, JPG, or WebP image that does not exceed 250 kilobytes.",
  "غيّر الاسم أو اختر صورة قبل الحفظ.": "Change the name or select an image before saving.",
  "تحدث اسم البوت أو صورته في Discord.": "Speak the bot's name or its image in Discord.",
  "بدون لقب خاص": "Without a custom title",
  "البطاقات والروابط": "Cards and links",
  "تعذر فحص الصلاحيات الآن؛ تحقق من رتبة البوت داخل Discord.": "It is currently not possible to check the permissions; check the bot's role within Discord.",
  "تغير لقب البوت داخل السيرفر في Discord.": "Change the bot's title within the server in Discord.",
  "حُفظ اسم البوت داخل لوحة التحكم.": "The bot's name is saved within the control panel.",
  "فصل هذا البوت؟": "Separate this bot?",
  "ستتوقف اللوحات والتفاعلات التي نشرها هذا البوت حتى تعيد ربطه. لن تُحذف رسائله السابقة من Discord.": "The boards and interactions you posted by this bot will stop until it is reconnected. Previous messages from the bot will not be deleted from Discord.",
  "فُصل البوت. يمكنك ربطه من جديد عند الحاجة.": "The bot has been disconnected. You can reconnect it if needed.",
  "اختر صورة PNG أو JPG أو WebP أصغر من 10 ميجابايت.": "Choose a PNG, JPG, or WebP image smaller than 10 megabytes.",
  "الصورة كبيرة جدًا بعد الضغط. اختر صورة أصغر.": "The image is too large after compression. Choose a smaller image.",
