  "اختر قالبًا، عدّل كل تفاصيله، ثم شاهد الفرق قبل أن يلمس البوت سيرفرك.": "Select a template, edit all details, then watch the team before the bot touches your server.",
  "نحمّل القوالب…": "Upload Templates...",
  "تعديلاتك محفوظة في هذه الجلسة؛ لم تُطبق على Discord.": "Your changes are saved in this session; they have not been applied to Discord.",
  "تعديلاتك محفوظة أثناء فتح الصفحة فقط. راجع القالب قبل تحديث الصفحة، خصوصًا الصور الكبيرة.": "Your changes are saved only while the page is open. Review the template before updating the page, especially large images.",
