  "المنصات": "Platforms",
  "التنصيب": "Installation",
  "📺・يوتيوب": "📺・YouTube",
  "🟣・تويتش": "🟣・Twitch",
  "🟢・كيك": "🟢・Kik",
  "🎬・تيك-توك": "🎬・TikTok",
  "أضف القنوات التي يحتاجها مجتمعك فقط. تُنشأ للقراءة، مع السماح لصانع المحتوى بالنشر إن كانت رتبته موجودة في القالب.": "Add only the channels your community needs. It's read-only, allowing content creators to post if a role is present in the template.",
  "هذه الخطوة تجهّز قناة ورابط منصتك. تنبيهات البث والمقاطع التلقائية غير مفعّلة هنا، وتحتاج ربط المنصة بخدمة تنبيهات مستقلة.": "This step prepares a channel and your platform link. Broadcast notifications and automatic clips are disabled here and require independent notification service integration with the platform.",
  "القناة مضافة إلى القالب، ويمكن تعديلها في خطوة القنوات.": "The channel is added to the template, and can be edited in the channel step.",
  "قناة مخصصة لنشر محتواك يدويًا وروابط منصتك.": "A dedicated channel for manually publishing your content and links to your platform.",
  "تحديث رابط القناة": "Update the channel link",
  "＋ إضافة قناة المنصة": "＋ Add platform channel",
  "وصل القالب إلى الحد: 85 قناة. احذف قناة قبل الإضافة.": "The template has reached the limit: 85 channels. Delete a channel before adding.",
  "وصل القالب إلى الحد: 25 تصنيفًا. احذف تصنيفًا قبل الإضافة.": "The template has reached the limit: 25 categories. Delete a category before adding.",
  "📡・منصات صانع المحتوى": "📡・Content platforms",
  "حُفظت قناة المنصة في المسودة. ستُنشأ بعد المراجعة والتأكيد.": "The platform channel was saved in the draft. It will be created after review and confirmation.",
  "التشغيل التلقائي": "Automatic operation",
  "هذا الاسم يعرّف مسودتك؛ لا يغيّر اسم سيرفرك. انتقل بين الخطوات بحرية، ولن يبدأ التنفيذ حتى تراجع التغييرات وتؤكدها.": "This name defines your draft; it does not change your server name. You can freely switch between steps, and execution will not start until the changes are reviewed and confirmed.",
  "مصدر الإلهام للقالب ↗": "Inspiration for the template ↗",
  "تُنشر هذه البطاقات مرة واحدة في القنوات المحددة بعد المراجعة. عدّل النصوص أو احذف البطاقة قبل التنصيب؛ كل بطاقة منشورة تُحسب تغييرًا واحدًا.": "These cards will be published once in the specified channels after review. Modify the text or delete the card before installation; each published card counts as one change.",
  "＋ بطاقة بداية": "Start Card",
  "بطاقة وصورة العضو وقناة النشر": "Member Card and Publication Channel",
  "لوحة الدعم": "Support Board",
  "زر التذكرة وفريق الاستجابة والتصميم": "Ticket Button, Response Team, and Design",
  "سجلات النشاط": "Activity Logs",
  "سجل موحد أو مسارات مخصصة": "Unified Log or Custom Paths",
  "بطاقات البداية": "Start Cards",
  "إرشادات قابلة للتعديل داخل القنوات": "Editable Guidelines Within Channels",
  "متوقفة": "Stopped",
  "مميزات إضافية لهذا القالب": "Additional Features for This Template",
  "اختر ما يناسب سيرفرك فقط. لا تُنشر الميزة ولا تُحسب من الرصيد حتى تفعّلها، ويمكنك معاينتها قبل التنصيب.": "Choose What Fits Your Server Only. The Feature Is Not Published and Not Counted Toward Your Balance Until You Activate It. You Can Preview It Before Installation.",
  "اختيارية": "Optional",
  "تفعيل الميزة مع هذا القالب": "Enable the feature with this template",
  "إزالة الصورة": "Remove the image",
  "مراحل إعداد القالب": "Template setup stages",
  "→ السابق": "→ Previous",
  "التالي ←": "Next ←",
  "مكتبة القوالب الجاهزة": "Ready Templates Library",
  "تصفح القوالب واختر نقطة البداية المناسبة لسيرفرك.": "Browse templates and choose the starting point suitable for your server.",
  "اختر قالبًا لتفتح صفحة إعداداته ومعاينته. التنصيب يحتفظ بالموجود؛ الاستبدال ينشئ الجديد أولًا ثم يعرض ما سيُحذف للمراجعة. حذف القنوات يحذف رسائلها من Discord.": "Choose a template to open its settings and preview. Installation retains existing settings; replacement creates a new one first and displays what will be deleted for review. Deleting channels removes their messages from Discord.",
  "→ مكتبة القوالب": "→ Templates Library",
  "إعادة القالب الأصلي": "Original Template",
  "عدّل الأسماء والترتيب والصلاحيات والميزات، ثم راجع الفروق والتطبيق.": "Edit names, order, permissions, and features, then review differences and apply them.",
  "لا يمنح أي قالب صلاحية Administrator. الرتب الإدارية محدودة للإشراف ويمكن تعديلها قبل التنفيذ.": "No template grants Administrator permissions. Administrative roles are limited for supervision and can be edited before execution.",
  "＋ رتبة": "+ role",
  "افتح الميزة التي تريد تخصيصها، وشاهد معاينتها قبل التنصيب.": "Open the feature you want to customize, and preview it before installation.",
  "بطاقة ترحيب لكل عضو جديد": "Welcome card for each new member",
  "لوحة دعم بزر فتح تذكرة": "Support ticket board with a button to open a ticket",
  "سجلات نشاط السيرفر والأوامر": "Activity logs of the server and commands",
  "اختر الأحداث والقنوات التي تريد تسجيلها.": "Select the events and channels you want to record.",
  "تنصيب بجانب القنوات والرتب الموجودة": "Install next to existing channels and roles",
  "استبدال الموجود بعد بناء القالب الجديد": "Replace the existing one with the new template",
  "الاستبدال يحذف قنوات Discord ورسائلها ورتب الأعضاء القديمة؛ العناصر التي يحميها Discord أو تعلو رتبة البوت تبقى ويظهر اسمها في المراجعة.": "Replacement deletes Discord channels and their messages and old member roles; elements protected by Discord or higher than the bot's role remain and their names are displayed in the review.",
  "معاينة التغييرات والمراجعة ←": "Preview changes and review ←",
