  "تخصيص القالب": "Customize Template",
  "لا يبدأ أي تغيير قبل مراجعتك، وسنتحقق من اتصال البوت وصلاحياته.": "No changes will be made until you review them, and we will check the bot's connection and permissions.",
  "إدارة ربط البوت": "Bot Link Management",
  "سيُفحص الاتصال قبل التنفيذ": "The connection will be checked before execution",
  "اربط بوتك لتستخدمه في التنفيذ": "Link your bot to use it for execution",
  "إيقاف هذا القالب؟": "Stop this template?",
  "ستبقى العناصر التي نُفذت في Discord، وستتوقف الخطوات المتبقية. يُحتسب من رصيدك ما اكتمل فقط، ويمكنك إنشاء مراجعة جديدة لاحقًا.": "The elements executed in Discord will remain, and the remaining steps will stop. Only the completed portion will be deducted from your balance, and you can create a new review later.",
  "نعم، أوقف القالب": "Yes, stop the template",
  "وصل طلب الإيقاف. سيقف التنفيذ بعد الخطوة الجارية؛ افتح القائمة لتتابع الحالة.": "Stop request received. Execution will stop after the current step; open the menu to check the status.",
  "إعادة القالب الأصلي؟": "Restore the original template?",
  "ستُزال تعديلات هذه الصفحة فقط. لن يتغير سيرفرك في Discord.": "Only the modifications on this page will be removed. Your server in Discord will not change.",
  "إعادة الأصل": "Restore original",
  "يبقي كل القنوات والرتب الحالية ويضيف عناصر القالب فقط.": "It will keep all existing channels and roles and add only the template elements.",
  "ينشئ القالب أولًا، ثم يحذف القنوات والرتب القديمة التي تسمح صلاحيات البوت بحذفها. ستراجع قائمة الحذف قبل التأكيد.": "The template will be created first, then the old channels and roles will be deleted, allowing the bot to delete them. A deletion list will be reviewed before confirmation.",
  "رفع الرتبة": "Promote the role",
  "تنزيل الرتبة": "Download role",
  "من يستطيع النشر في هذه القناة؟": "Who can post in this channel?",
  "الإدارة والبوت فقط": "Management and bot only",
  "إزالة الصورة الحالية": "Remove Current Image",
  "أعلى": "Top",
  "أسفل البطاقة": "Bottom of Card",
  "أعلى البطاقة": "Top of Card",
  "ضع صورة العضو داخل التصميم المرفوع": "Place Member Image Inside the Raised Design",
  "فوق البطاقة (بدون دمج)": "Above the Card (Without Merging)",
  "عند الدمج تُستخدم صورة العضو الحقيقية عند انضمامه. معاينة الصورة هنا مثال. التصميم الثابت يُجهّز بمقاس 1200×480 تلقائيًا.": "When merging, the real member image is used when they join. Preview of the image here is an example. The static design is automatically prepared in 1200×480 size.",
  "إزالة صورة الدعم": "Remove Support Image",
  "أسفل النص": "Below Text",
  "شعار صغير داخل البطاقة": "Small logo inside the card",
  "دمج شعار دائري داخل تصميمك": "Integrate a circular logo into your design",
  "ارفع تصميمًا ثابتًا وشعارًا، ثم حرّك موضع الشعار. تظهر النتيجة في المعاينة قبل النشر.": "Upload a static design and logo, then move the logo position. The result appears in the preview before publishing.",
  "اختر سجلًا واحدًا لكل الأحداث، أو وزّعها بقواعد تربط عدة قنوات مصدر بقناة سجل واحدة. نص الرسالة المحذوفة يظهر فقط إذا كان متاحًا للبوت من Discord، وتُجمع الإشعارات لتفادي الإرسال المفرط.": "Select one log channel per event, or distribute them based on rules that connect multiple source channels to one log channel. Deleted message text is only shown if it's available for the bot from Discord, and notifications are aggregated to avoid excessive sending.",
  "رسالة جديدة": "New message",
  "تعديل رسالة": "Edit message",
  "حذف رسالة": "Delete message",
  "دخول صوتي": "Voice entry",
  "خروج صوتي": "Voice exit",
  "أوامر البوت": "Bot commands",
  "سجل واحد يجمع كل الأحداث": "One log channel that collects all events",
  "توزيع مخصص حسب القنوات ونوع الحدث": "Custom distribution based on channels and event type",
  "لكل قاعدة اختر نوع اللوق والقنوات التي تراقبها وقناة الاستقبال. يمكن جمع عدة مصادر في سجل واحد، أو تخصيص سجل مستقل للقنوات الخاصة.": "For each server, select the type of log and the channels you monitor, and choose a reception channel. You can combine multiple sources into one log, or assign a separate log for the private channels.",
  "＋ أضف قاعدة لوق": "＋ Add a log server",
  "لوق القناة الخاصة اختر له قناة استقبال 🔒 خاصة حتى لا يظهر للأعضاء.": "For the private channel, select a reception channel 🔒 that is private so it doesn't appear to members.",
  "🔒 خاصة": "🔒 Private",
  "# عامة": "# General",
  "اختر صورة PNG أو JPG أو WebP أو GIF بحجم 8 ميجابايت أو أقل.": "Choose a PNG or JPG or WebP or GIF image with a size of 8 megabytes or less.",
  "دمج الشعار داخل التصميم يحتاج PNG أو JPG أو WebP. استخدم GIF في العرض العادي.": "Embedding the logo into the design requires PNG or JPG or WebP. Use GIF for regular display.",
  "بعد تفعيل الدمج، أعد رفع التصميم ليُجهّز بمقاس البطاقة.": "After enabling the embedding, re-upload the design to be prepared in the card size.",
  "بطاقة جديدة": "New card",
  "اكتب هنا معلومات مفيدة لأعضاء سيرفرك.": "Write here useful information for your server members.",
  "قناة-جديدة": "Channel-new",
  "جارٍ تجهيز المراجعة…": "Processing the review…",
  "الترحيب الحالي": "Current Welcome",
  "سيضيف القالب ترحيبًا تلقائيًا جديدًا لهذا السيرفر.": "The template will add a new automatic welcome for this server.",
  "الترحيب غير مفعّل في القالب، لكن استبدال الهيكل سيحذف قناته القديمة؛ سيتوقف الترحيب الحالي.": "The welcome is disabled in the template, but replacing the structure will delete the old channel; the current welcome will stop.",
  "الترحيب غير مفعّل في القالب؛ سيبقى إعداد الترحيب الحالي كما هو.": "The welcome is disabled in the template; the current welcome settings will remain as they are.",
  "الترحيب غير مفعّل في القالب، ولا يوجد ترحيب سابق ليتغير.": "The welcome is disabled in the template; there is no previous welcome to change.",
  "مراجعة القالب قبل التنفيذ": "Review the template before execution",
  "راجعت الهيكل والصلاحيات وقائمة الحذف، وأوافق على التنفيذ.": "The structure and permissions and delete list have been reviewed, and I agree to execution.",
  "استبدال الهيكل القديم": "Replace the old structure",
