  "ميزة:": "Feature:",
  "حذف القنوات يمحو الرسائل نهائيًا من Discord، وحذف الرتب يزيلها من الأعضاء. لا يمكن استعادة المحتوى من هذه المعاينة.": "Deleting channels permanently deletes messages from Discord, and deleting roles removes them from members. Content cannot be recovered from this preview.",
  "لن تُحذف القنوات أو الرتب الحالية.": "The current channels and roles will not be deleted.",
  "نعم، نفّذ القالب": "Yes, apply the template",
