  "إنشاء": "Create",
  "لن ينقلها البوت إلى التصنيفات الجديدة. يمكنك ترتيبها لاحقًا من Discord، أو مراجعة خيار الاستبدال إذا أردت حذف القديم.": "The bot will not transfer it to the new categories. You can organize it later from Discord, or review the replacement option if you want to delete the old one.",
