  "اختر تصميم PNG أو JPG أو WebP لا يتجاوز 25 ميجابايت.": "Choose a PNG or JPG or WebP design not exceeding 25 megabytes.",
  "أبعاد الصورة كبيرة جدًا. استخدم صورة أقل من 50 مليون بكسل.": "The image dimensions are too large. Use an image with less than 50 million pixels.",
