  "التصميم كبير بعد التجهيز. استخدم صورة أبسط أو أصغر.": "The design is too large after processing. Use a simpler or smaller image.",
  "الشعار كبير جدًا بعد التجهيز. اختر صورة أبسط.": "The logo is too large after processing. Choose a simpler image.",
  "اختر صورة شعار PNG أو JPG أو WebP حتى 25 ميجابايت.": "Choose a PNG, JPG, or WebP logo image up to 25 MB.",
  "تعذر تجهيز الشعار. استخدم صورة أبسط.": "The logo cannot be processed. Use a simpler image.",
  "ارفع تصميمًا وشعارًا بصيغة PNG أو JPG أو WebP حتى 25 ميجابايت لكل صورة.": "Upload a PNG, JPG, or WebP design and logo up to 25 MB each.",
  "التصميم مع الشعار كبير بعد التجهيز. استخدم خلفية أبسط.": "The design with the logo is too large after processing. Use a simpler background.",
