  "GIF يبقى متحركًا في العرض العادي؛ دمج الشعار داخل التصميم يحتاج صورة ثابتة.": "GIF remains animated in normal display; merging the logo into the design requires a static image.",
  "ارفع صورة ثابتة لاستخدام الشعار الدائري أو التصميم.": "Upload a static image for use with the circular logo or design.",
  "GIF المتحرك يُعرض كصورة عادية. اختر صورة ثابتة لدمج الشعار.": "Animated GIF is displayed as a regular image. Choose a static image to integrate the logo.",
  "غلاف الحدث GIF يجب ألا يتجاوز 2 ميجابايت.": "Event cover GIF should not exceed 2 megabytes.",
  "اختر غلاف PNG أو JPG أو WebP حتى 25 ميجابايت؛ سيُجهز للمقاس المناسب تلقائيًا.": "Choose a PNG or JPG or WebP image up to 25 megabytes; it will be automatically scaled to the appropriate size.",
  "تعذر تجهيز غلاف الحدث ضمن الحجم المسموح. جرّب صورة أبسط.": "The event cover could not be prepared within the allowed size. Try a simpler image.",
  "اختر GIF أو MP4 أو MOV بحجم لا يتجاوز 20 ميجابايت.": "Choose a GIF or MP4 or MOV file no larger than 20 megabytes.",
  "تعذر قراءة الملف المتحرك.": "The moving file could not be read.",
  "حدد قناة اللوحة ورتبة الدعم ← راجع النص والبنر ← أكد النشر ← العميل يفتح تذكرة خاصة ← الفريق يستلمها ويتابعها": "Select the channel and support level ← review the text and banner ← confirm publishing ← the client opens a private ticket ← the team receives it and follows up",
  "جيف آواي": "Jeff Awai",
  "حدد الجائزة والمدة والقناة ← راجع البطاقة والبنر ← أكد النشر ← يتفاعل الأعضاء مع زر المشاركة": "Select the prize and duration and the channel ← review the card and banner ← confirm publishing ← members interact with the participation button",
  "حدد السؤال والخيارات والصور ← راجع المعاينة ← انشر ← يصوّت الأعضاء وتظهر النتائج": "Select the question and options and images ← review the preview ← publish ← members vote and results are displayed",
  "جهز إعلان الفعالية ← فعّل زر التسجيل إن أردت ← راجع المعاينة ← انشر ويتحدث عدّاد المشاركين": "Prepare the event announcement ← activate the registration button if desired ← review the preview ← publish and the participant counter starts counting",
  "اختر قناة صوتية أو مكانًا آخر ← اضبط الموعد والغلاف ← راجع شكل الحدث ← أنشئه في Events داخل Discord": "Choose a voice channel or another location ← adjust the time and cover ← review the event appearance ← create it in Events within Discord",
  "اختر قناة الترحيب والبطاقة ← راجع المعاينة ← فعّلها ← يرحّب البوت تلقائيًا بكل عضو جديد": "Select the welcome channel and the badge ← Preview ← Enable it ← The bot will automatically welcome new members",
  "اختر القناة وعدّل القوانين ← اختر طريقة عرض البطاقة واللون والصورة ← راجع المعاينة ← انشر": "Select the channel and edit the rules ← Select the badge display method, color, and image ← Preview ← Publish",
  "حدد القناة والنص والصورة إن وجدت ← راجع المحتوى وموضع الصورة ← أكد النشر في Discord": "Select the channel, text, and image if it exists ← Review the content and image position ← Confirm publishing in Discord",
