  "إيقاف التسجيل": "Stop recording",
  "إرفاق صورة أو ملف نصي": "Attach an image or text file",
  "تسجيل صوت وتحويله إلى نص": "Record audio and convert it to text",
  "تصغير المكتبة": "Minimize the library",
  "تنفيذ تعديلات AI على القنوات والرتب": "Apply AI edits to channels and roles",
  "سيستخدم AI بوتك الخاص بعد مراجعة الصلاحيات.": "The AI bot will be used after reviewing the permissions.",
  "سيستخدم AI بوت ديسكوكو بعد مراجعة الصلاحيات.": "The AI bot Diskoko will be used after reviewing the permissions.",
  "سيُفصل البوت الخاص عن هذا السيرفر. المنشورات التفاعلية السابقة قد تتوقف حتى تعيد ربطه. هل تريد المتابعة؟": "The private bot will be disconnected from this server. Previous interactive posts may stop until it is reconnected. Do you want to continue?",
  "فُصل بوتك الخاص. سيستخدم AI بوت ديسكوكو في المنشورات الجديدة.": "Your custom bot. The AI bot Diskoko will be used for new posts.",
  "فعّل Message Content Intent لعرض نص الرسائل المحذوفة، وServer Members Intent للترحيب التلقائي. لا تضع الرمز في المحادثة أو في رسالة Discord.": "Enable Message Content Intent to display deleted message text, and Server Members Intent for automatic welcome messages. Do not place the symbol in the conversation or in Discord messages.",
  "شرح الإنشاء والإضافة خطوة بخطوة ↗": "Step-by-step explanation of creation and addition ↗",
  "ألصق Bot Token هنا": "Paste Bot Token here",
  "سيرفرك": "Your server",
  "تعذر التحقق من الربط الآن. حدّث الصفحة للمحاولة مجددًا.": "Verification of the connection is currently not possible. Refresh the page to try again.",
  "اكتب جوابًا واحدًا واضحًا": "Write a single clear response",
  "الميزة مستقلة عن القوالب الجاهزة. راجع اللوحة والقنوات والصلاحيات قبل النشر؛ يُحسب تغيير واحد عند نجاح التركيب فقط.": "The feature is independent of the ready templates. Review the board, channels, and permissions before publishing; only one change is counted upon successful installation.",
