  "٣. شكل اللوحة": "3. Board appearance",
  "عدّل المحتوى والوظيفة التي سيستخدمها العضو، ثم راجع المعاينة. فتح المراجعة لا ينشر؛ التنفيذ بعد التأكيد النهائي.": "Modify the content and function that the member will use, then review the preview. Opening the review does not publish; execution occurs only after final confirmation.",
