  "من خيارين إلى ٩ خيارات؛ يمكن وضع صورة أو GIF مصغّر لكل خيار. لكل عضو صوت واحد قابل للتغيير.": "Two to 9 choices, with an optional image or GIF thumbnail per choice. Each member has one vote and may change it.",
