  "دائرة / Circle": "Circle",
  "مربع / Square": "Square",
  "يمكن دمج صورة العضو داخل PNG أو JPG أو WebP أو GIF متحرك. الحد الأقصى للملف 20 ميجابايت. عند دمج صورة العضو، يلزم ألا يتجاوز GIF مئة إطار أو 60 مليون بكسل عبر الإطارات. للملفات الأكبر، أوقف الدمج وسيظهر GIF كما هو.": "You can embed the member’s avatar into a PNG, JPG, WebP or animated GIF. The file limit is 20 MB. With avatar embedding enabled, GIFs must stay within one hundred frames and 60 million total frame pixels. For larger files, disable embedding to display the original GIF.",
  "👋 أهلًا بك في مجتمعنا!": "👋 Welcome to Our Community!",
