  "بطاقة واحدة بنص حر متعدد الأسطر. الترقيم اختياري وتكتبه بنفسك. الحد الأقصى 3500 حرف.": "A single card with free-form multi-line text. Numbering is optional and you can write it yourself. Maximum 3500 characters.",
  "＋ أضف قسمًا أو قانونًا": "+ Add a Section or Rule",
  "لكل قسم عنوان اختياري ونص متعدد الأسطر. يمكنك إضافة حتى 100 قسم، وتُقسّم البطاقات الطويلة تلقائيًا على رسائل متتابعة.": "Each section has an optional title and multi-line text. You can add up to 100 sections, and long cards are automatically split into consecutive messages.",
