  "سيُعدّل هذا التأكيد إعدادات النظام أو رسالته الحالية في القناة نفسها، دون إنشاء لوحة جديدة. تبقى المشاركات والأصوات محفوظة.": "This verification will update the system settings or current message in the same channel, without creating a new board. The participants and audio will be preserved.",
  "الصورة المرفقة مرجع للتصميم فقط ولن تُنشر. عدّل النص واللون وصورة العضو هنا. توسيط صورة العضو يحتاج رفع خلفية للتصميم المركب. شكل بطاقة Discord وخطوطها يخضعان لحدود Discord.": "The attached image is for design reference only and will not be published. Modify the text and color of the member here. The member image requires a background upload for the composite design. The Discord card shape and lines are subject to Discord's restrictions.",
