  "تعذر تأكيد تعديل اللوحة. أُوقفت إعادة التنفيذ حتى تُراجع الحالة.": "Unable to confirm the board modification. Execution has been paused until the status is reviewed.",
  "تعذر قراءة سجل قناة اللوحة. امنح البوت قراءة سجل الرسائل.": "Unable to read the channel log. Grant the bot message history access.",
  "تعذر نشر اللوحة. تحقق من صلاحيات البوت في القناة المحددة.": "Unable to publish the board. Check the bot's permissions in the specific channel.",
