  "القناة": "Channel",
  "تغيّرت إعدادات السيرفر بعد المعاينة.": "Server settings have changed after preview.",
  "اختر بوت ديسكوكو أو بوتك الخاص.": "Select Diskoko bot or your own bot.",
  "بوتك الخاص غير متصل. اربطه من إعدادات السيرفر أولًا.": "Your bot is not connected. Connect it first from server settings.",
  "بوت ديسكوكو غير متصل الآن. اختر بوتك الخاص أو انتظر عودته.": "Diskoko bot is not connected now. Select your own bot or wait for it to return.",
  "تعذرت قراءة السيرفر من Discord. تحقق من اتصال البوت وصلاحياته.": "Unable to read the server from Discord. Check the bot's connection and permissions.",
  "مراجعة القالب غير موجودة.": "Template preview is not available.",
  "القالب المختار غير موجود.": "Selected template is not available.",
  "الترحيب": "Welcome",
  "الدعم": "Support",
  "اختر التنصيب أو الاستبدال.": "Select Installation or Replacement.",
  "إحدى قنوات مصدر اللوق لم تعد موجودة في السيرفر. راجع قواعد اللوق.": "One of the source channels is no longer present in the server. Check the channel settings.",
  "الاستبدال سيحذف قنوات اللوق القديمة. اختر قنوات من القالب كمصادر، أو استخدم التنصيب بجانب الموجود.": "Replacement will delete old source channels. Select channels from the template as sources, or use the existing ones alongside.",
  "إحدى قواعد اللوق تراقب قناة خاصة وتُرسل إلى قناة عامة. اختر قناة سجل خاصة حتى لا ينكشف نشاطها.": "One of the channel rules is monitoring a private channel and sending it to a public channel. Select a private log channel to keep its activity hidden.",
  "بناء القالب قبل حذف القديم قد يتجاوز حد قنوات Discord. احذف بعض القنوات يدويًا أولًا.": "Building the template before deleting the old one may exceed Discord's channel limit. Delete some channels manually first.",
  "بناء القالب قبل حذف القديم قد يتجاوز حد رتب Discord. احذف بعض الرتب يدويًا أولًا.": "Building the template before deleting the old one may exceed Discord's role limit. Delete some roles manually first.",
  "إيقاف مهام القنوات القديمة": "Stop old channel tasks",
  "ترتيب القنوات والرتب": "Sort channels and roles",
  "اكتمل تنصيب القالب بالفعل؛ لا يمكن إيقافه. راجع القنوات والرتب لتعديل ما أُنشئ.": "The template has been installed successfully; it cannot be stopped. Review the channels and roles to adjust what was created.",
  "اكتمل التنصيب قبل وصول طلب الإيقاف. راجع القنوات والرتب لتعديل ما أُنشئ.": "The installation is complete before the stop request. Review the channels and roles to adjust what was created.",
  "هناك عملية أخرى تعمل على هذا السيرفر. حاول بعد اكتمالها.": "There is another process running on this server. Try again after it is complete.",
  "أُوقف هذا التنصيب. ابدأ مراجعة جديدة إذا أردت تركيب القالب لاحقًا.": "Stop this installation. Start a new review if you want to install the template later.",
  "راجع اسم السيرفر ونوع التنفيذ وأكد التغييرات أولًا.": "Review the server name and execution type and confirm the changes first.",
  "تغيّر إعداد الترحيب بعد مراجعة القالب. حدّث المراجعة لتشاهد ما سيُستبدل قبل التنفيذ. لم نغيّر الترحيب الحالي.": "Change the welcome settings after reviewing the template. Update the review to see what will be replaced before execution. We have not changed the current welcome message.",
  "الترحيب التلقائي يحتاج بوتًا متصلًا مع تفعيل Server Members Intent. راجع الربط قبل التنفيذ.": "The automatic welcome requires a bot connected with Server Members Intent enabled. Review the connection before execution.",
  "الميزات التفاعلية تحتاج بوتًا متصلًا قبل النشر. تحقق من ربط البوت المختار.": "Interactive features require a bot connected before publishing. Check the selected bot's connection.",
  "تعذر التحقق من صلاحيات البوت داخل السيرفر. أعد ربطه ثم حاول.": "Unable to verify the bot's permissions within the server. Reconnect it and try again.",
  "البوت يحتاج إدارة القنوات والرتب، ومع لوحة الدعم يحتاج إرسال الرسائل والروابط المضمنة. عدّل صلاحياته قبل التنفيذ.": "The bot needs permissions to manage channels and roles. For support, it also needs permission to send messages and embedded links. Adjust its permissions before execution.",
  "بعض صلاحيات الرتب في القالب أعلى من صلاحيات البوت. عدّل نوع الرتب أو صلاحيات البوت أولًا.": "Some role permissions in the template are higher than the bot's permissions. Adjust the role type or the bot's permissions first.",
  "تعذر التحقق من موضع رتبة البوت. لن نحذف أي رتبة.": "Unable to verify the bot's role position. We will not delete any roles.",
  "لم يعد رصيد التغييرات المتبقي يكفي هذا القالب، بما فيه الرتب. راجع الاستخدام أو الباقة.": "The remaining change quota is insufficient for this template, including roles. Review usage or plan.",
  "تصنيف القناة لم يكتمل بعد. حاول المتابعة.": "The channel category is not yet complete. Try again.",
  "رتبة القناة الخاصة لم تجهز بعد.": "The channel's private role is not yet prepared.",
  "رتبة النشر في القناة لم تجهز بعد.": "The publishing role in the channel is not yet prepared.",
  "قناة الترحيب غير جاهزة.": "The welcome channel is not yet ready.",
  "قناة الدعم غير جاهزة.": "Support channel is not ready.",
  "تعذر فحص رسائل قناة الدعم قبل النشر. تحقق من صلاحية قراءة سجل الرسائل.": "Cannot check messages in the support channel before publishing. Check the validity of message reading logs.",
