  "بعض قنوات مصادر اللوق أو وجهاته لم تجهز.": "Some message source or destination channels are not ready.",
  "هناك رسالة تُرسل الآن في إحدى القنوات القديمة. انتظر اكتمالها ثم تابع الاستبدال.": "There is a message being sent now in one of the old channels. Wait for it to complete then proceed with replacement.",
