  "ابحث في الإجراءات": "Search actions",
  "اختر إجراءً وأرسل القالب كما هو. أكمل بياناته في بطاقة المراجعة، وشاهد شكله في سيرفرك قبل التأكيد.": "Choose an action, complete its review fields and inspect the preview before confirming.",
  "مساعدك لتنظيم السيرفر. محادثاتك محفوظة لهذا السيرفر ويمكنك الرجوع إليها.": "Your server assistant. Conversations are saved for this server.",
  "خلّ AI ينشر وينفذ باسم بوت سيرفرك بعد مراجعتك. يبقى بوت ديسكوكو الخيار الأساسي حتى تربط بوتك.": "Use your own bot after reviewing each change. Diskoko is the default until you connect a bot.",
