  "أدوات الإدارة والمتابعة": "Management and monitoring tools",
  "تحكم ببنية سيرفرك من مكان واحد. كل تعديل يمر بمراجعة قبل تطبيقه.": "Manage your server structure in one place. Review every change before applying it.",
  "لتحكم كامل، امنح البوت صلاحية Administrator وضع رتبته فوق الرتب التي سيعدلها.": "For full control, grant the bot Administrator permission and place its role above the roles it manages.",
  "تحقق من البوت المختار أدناه قبل التعديل. يجب أن تكون رتبته فوق الرتب المستهدفة، ويحتاج صلاحيات إدارة القنوات والرتب.": "Check the selected bot before editing. Its role must be above the target roles, with Manage Channels and Manage Roles permissions.",
