  "إرسال بعد موافقتك على الرسالة والموعد.": "Sent after you approve the message and time.",
  "لا تُفعّل إشارات الجميع أو الرتب تلقائيًا. قد يتأخر الإرسال إذا توقفت خدمة الاستضافة.": "Everyone and role mentions are not enabled automatically. Delivery may be delayed if hosting is interrupted.",
