  "كل تغيير في سجلك": "Every change in your history",
  "كل خطة تبين ما خُطط له وما اكتمل فعليًا. المسودة أو المحاولة الفاشلة بلا تنفيذ لا تستهلك رصيدًا.": "Each plan shows intended and completed changes. Drafts and failed attempts without applied changes do not consume your quota.",
