  "اتصال السيرفر وتفضيلات النشاط، في مكان واحد.": "Server connection and activity preferences, in one place.",
  "الحساب مرتبط": "Account connected",
  "ربط بوت التنفيذ": "Connect the executor bot",
  "بوت التنفيذ لهذا السيرفر": "Executor bot for this server",
  "اختر بوت ديسكوكو أو اربط بوتك الخاص ليكون المنفذ الافتراضي لأدوات السيرفر. القوالب الجاهزة تتيح اختيار بوتها عند المراجعة.": "Choose Diskoko or connect your own bot as the default executor. Ready templates let you select a bot during review.",
