  "أنت مالك السيرفر": "You own this server",
  "حالة الربط": "Connection status",
  "مراجعة ربط البوت": "Review bot connection",
  "بعد العودة من Discord سنعيد التحقق تلقائيًا. لا نطلب صلاحية Administrator.": "The connection is checked automatically when you return from Discord. Administrator permission is not requested.",
  "تفاصيل السيرفر": "Server details",
  "نسخ المعرّف": "Copy ID",
  "خصوصية إحصاءات النشاط": "Activity statistics privacy",
  "جمع النشاط غير مفعّل": "Activity collection is disabled",
  "يجمع البوت عدد الرسائل وأسماء المشاركين فقط، دون محتوى الرسائل، لمدة 30 يومًا. الإيقاف يمنع جمع أحداث جديدة.": "The bot collects message counts and participant names for 30 days, without message content. Disabling collection stops new events.",
  "عرض التحليلات": "View analytics",
  "نسخة من البنية الحالية": "Current structure snapshot",
  "نزّل القنوات والرتب للمراجعة أو التوثيق. الملف لا يحتوي رسائل الأعضاء، ولا يوفّر استعادة تلقائية للسيرفر.": "Download channels and roles for review or documentation. Member messages are excluded. This file does not automatically restore a server.",
  "تصدير بنية السيرفر": "Export server structure",
  "وضوح الصلاحيات، بداية الأمان.": "Clear permissions are the foundation of security.",
  "افحص بنية الصلاحيات وتحقق من التغييرات قبل تنفيذها.": "Inspect permissions and review changes before applying them.",
  "مراجعة قبل التطبيق": "Review before applying",
  "ضمن رحلة التعديل": "Part of the editing workflow",
  "إضافة القنوات والرتب وتعديلها تمر بخطة محفوظة وتأكيد منك قبل التنفيذ. تظهر العمليات المكتملة والمتعثرة منفصلة.": "Channel and role changes require a saved plan and your confirmation. Completed and failed operations are shown separately.",
  "حالة قراءة السيرفر": "Server access status",
  "القنوات والرتب متاحة": "Channels and roles are accessible",
  "نجاح القراءة لا يضمن صلاحية تعديل كل رتبة. يتحقق Discord من الصلاحيات وترتيب رتبة البوت أثناء التنفيذ.": "Read access does not guarantee permission to edit every role. Discord checks permissions and the bot’s role hierarchy during execution.",
  "رتب تملك صلاحية Administrator": "Roles with Administrator permission",
  "راجع الحاجة لهذه الصلاحية في Discord. لا يتم تعديلها تلقائيًا.": "Review whether this permission is needed in Discord. It is not changed automatically.",
  "رتبة في السيرفر": "Server role",
