  "أوامر البوتات المتصلة": "Connected bot commands",
  "كل أوامر هذا السيرفر مرتبة حسب البوت. اختر بوتًا لإدارة أوامره؛ لوحات الموسيقى ويوتيوب ونادي الأفلام تُعدّل من «اللوحات التفاعلية».": "Commands are organized by bot. Choose a bot to manage its commands. Edit music, YouTube and movie club panels under Interactive panels.",
